function tl0(z,L){const i={en:0,ja:1,ru:2,ar:3}[L],d=DICT[z];if(i===undefined)return tlN(z,L,d);if(d)return d[i];for(const r of RULES){const m=z.match(r[0]);if(m)return r[1+i](m)}return z}
