HELP.ru=['Держи палец на экране — рыбка плывёт вверх. Отпусти — медленно опускается.','<b>Осьминог</b> и <b>медуза</b> отнимают звезду. Осьминог опаснее всего, когда его щупальца светятся.','Удар о <b>скалу</b> или <b>льдину</b> отнимает одну звезду.','<b>Акула</b> съедает рыбку сразу! Увидел красное предупреждение — уплывай из красной полосы.','Попал в <b>сеть</b>? Не бойся: быстро нажимай на экран, чтобы вырваться.','<b>Щит золотой рыбки</b> спасает от одной опасности, но не от акулы.','Не врезайся в <b>жёлтую стену</b>: без щита вернёшься к контрольной точке.','Рыбу в пунктирном кружке можно поймать: <b>нажми на неё</b>. На крупную рыбу нужно нажать несколько раз. Готовь улов на <b>Кухне</b> и получай жемчуг.','Собранный жемчуг попадает в кошелёк. В <b>Магазине</b> можно купить щиты, помощников и облики.','За прохождение уровня дают звёзды. Сыграй ещё раз и найди скрытую четвёртую звезду!'];
HELP.ar=['اضغط على الشاشة لتسبح للأعلى، واتركها لتنزل ببطء.','لمس <b>الأخطبوط</b> أو <b>قنديل البحر</b> يُفقدك نجمة. الأخطبوط أخطر حين تضيء أذرعه.','الاصطدام بـ<b>صخرة</b> أو <b>قطعة جليد</b> يُفقدك نجمة كاملة.','<b>القرش</b> يأكل السمكة بلقمة واحدة! عندما ترى التحذير الأحمر اخرج من الشريط الأحمر.','علقت في <b>الشبكة</b>؟ لا تخف، اضغط على الشاشة بسرعة لتتحرر.','<b>درع السمكة الذهبية</b> يصدّ خطرًا واحدًا، لكنه لا يصدّ القرش.','لا تصطدم بـ<b>الجدار الأصفر</b>. بدون درع ستعود إلى نقطة الحفظ.','السمكة المحاطة بدائرة منقّطة يمكن صيدها: <b>المسها</b>. السمكة الكبيرة تحتاج لمسات أكثر. اطبخ صيدك في <b>المطبخ</b> لتكسب اللآلئ.','اللآلئ التي تجمعها تذهب إلى محفظتك. اشترِ من <b>المتجر</b> دروعًا ومساعدات وأشكالًا جديدة.','أكمل المرحلة لتكسب النجوم. العب مجددًا لتجد النجمة الرابعة المخفية!'];
TITLE.ru=['Рыбка,','плыви!'];TITLE.ar=['السمكة','السريعة'];
HELP.zh.splice(3,0,'碰到<b>海底</b>也会掉一颗星，别沉到底。');HELP.en.splice(3,0,'Touching the <b>sea floor</b> costs one star too. Don\'t sink to the bottom.');HELP.ja.splice(3,0,'<b>海のそこ</b>にさわっても星が1こへるよ。しずみすぎないで。');HELP.ru.splice(3,0,'Коснёшься <b>дна</b> — тоже потеряешь звезду. Не опускайся слишком низко.');HELP.ar.splice(3,0,'لمس <b>قاع البحر</b> يُفقدك نجمة أيضًا. لا تنزل إلى القاع.');

const lOrig=new WeakMap(),lOut=new WeakMap();
const PEARL='⚪',inPz=n=>{const p=n.parentNode;return p&&p.nodeType===1&&!!p.closest('.pz,.pearl')};
function pzHTML(o){return o.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'})[c]).split(PEARL).join('<i class="pearl">'+PEARL+'</i>')}
function pearlize(n,z,o){const p=n.parentNode;if(!p||o.indexOf(PEARL)<0)return false;const sp=document.createElement('span');sp.className='pz';sp.dataset.z=z;sp.innerHTML=pzHTML(o);p.replaceChild(sp,n);return true}
function locNode(n){if(inPz(n))return;const v=n.nodeValue;if(lOut.get(n)===v)return;lOrig.set(n,v);const o=tlKeep(v);lOut.set(n,o);if(pearlize(n,v,o))return;if(o!==v)n.nodeValue=o}
function locAll(){document.querySelectorAll('#app .pz').forEach(sp=>{sp.innerHTML=pzHTML(tlKeep(sp.dataset.z))});const w=document.createTreeWalker($('app'),NodeFilter.SHOW_TEXT),ns=[];let n;while((n=w.nextNode()))if(!inPz(n))ns.push(n);for(n of ns){const z=lOrig.has(n)?lOrig.get(n):n.nodeValue;lOrig.set(n,z);const o=tlKeep(z);lOut.set(n,o);if(pearlize(n,z,o))continue;if(n.nodeValue!==o)n.nodeValue=o}}
function applyLang(){const L=SAVE.lang;document.documentElement.lang=L==='zh'?'zh-CN':L;document.documentElement.dir=L==='ar'?'rtl':'ltr';
  FONT=({ja:'"Yusei Magic","Hiragino Maru Gothic ProN",',ru:'"Comfortaa",',ar:'"Baloo Bhaijaan 2","Geeza Pro","Noto Sans Arabic",',ko:'"Jua","Apple SD Gothic Neo","Malgun Gothic",',th:'"Itim","Thonburi","Noto Sans Thai",',it:'"Comfortaa",',de:'"Comfortaa",',es:'"Comfortaa",',fr:'"Comfortaa",'}[L]||'')+'"ZCOOL KuaiLe","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif';
  $('title').className=L==='zh'?'':'long';$('title').innerHTML=TITLE[L].map(x=>`<span>${x}</span>`).join('');
  {const h=document.querySelector('#sStart h1');if(h)h.innerHTML=$('title').innerHTML}$('helpList').innerHTML=HELP[L].map(x=>`<li>${x}</li>`).join('');
  document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('mint',b.dataset.lang===L));
  locAll();if(G)G.hudKey=''}
new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData'){if(m.target.nodeType===3)locNode(m.target)}else for(const a of m.addedNodes){if(a.nodeType===3)locNode(a);else if(a.nodeType===1){const w=document.createTreeWalker(a,NodeFilter.SHOW_TEXT),ns=[];let n;while((n=w.nextNode()))ns.push(n);ns.forEach(locNode)}}}}).observe($('app'),{subtree:true,childList:true,characterData:true});
$('langRow').onclick=e=>{const b=e.target.closest('[data-lang]');if(!b)return;SAVE.lang=b.dataset.lang;persist();SFX.tap();applyLang();
  if(b.dataset.lang==='zh'){const n=Date.now();devTap=n-devT<1500?devTap+1:1;devT=n;if(devTap>=5&&!window.XY_APP){devTap=0;SAVE.dev=SAVE.dev?0:1;persist();refreshMenu();toast(SAVE.dev?'开发者模式已开启，主菜单右上角有扳手按钮':'开发者模式已关闭',3)}}else devTap=0};
